mapper.select:
select  log.*,
    t.title as title, t.namespace as namespace, t.task_type
from zt_task_cron t
inner join zt_task_log log on t.id = log.task_id

    t.is_deleted = false and t.is_dir = false

        and t.title like #{qlike}


        and t.id = #{taskId}


        and t.namespace = #{namespace}


        and t.task_type = #{taskType}


        and log.task_status = #{taskStatus}


        and t.team_id = #{teamId}
